import json
from itertools import permutations

singers = ["Kammer", "Lugo", "Trillo", "Waite", "Yoshida", "Zinn"]
recorded = {"Kammer", "Lugo"}

def valid(order):
    # order[i] is the singer at audition slot i+1
    slot = {s: i + 1 for i, s in enumerate(order)}
    # Fourth audition cannot be recorded
    if order[3] in recorded:
        return False
    # Fifth audition must be recorded
    if order[4] not in recorded:
        return False
    # Waite earlier than both recorded auditions
    if not (slot["Waite"] < slot["Kammer"] and slot["Waite"] < slot["Lugo"]):
        return False
    # Kammer earlier than Trillo
    if not slot["Kammer"] < slot["Trillo"]:
        return False
    # Zinn earlier than Yoshida
    if not slot["Zinn"] < slot["Yoshida"]:
        return False
    # Given: Kammer immediately before Yoshida
    if slot["Yoshida"] != slot["Kammer"] + 1:
        return False
    return True

schedules = [p for p in permutations(singers) if valid(p)]

def slot_of(order, name):
    return order.index(name) + 1

options = {
    "A": ("Kammer's audition is second", lambda o: slot_of(o, "Kammer") == 2),
    "B": ("Trillo's audition is fourth", lambda o: slot_of(o, "Trillo") == 4),
    "C": ("Waite's audition is third", lambda o: slot_of(o, "Waite") == 3),
    "D": ("Yoshida's audition is sixth", lambda o: slot_of(o, "Yoshida") == 6),
    "E": ("Zinn's audition is second", lambda o: slot_of(o, "Zinn") == 2),
}

possible = []
for key, (_, test) in options.items():
    if any(test(o) for o in schedules):
        possible.append(key)

final = possible[0] if len(possible) == 1 else ("UNSUPPORTED" if not possible else "AMBIGUOUS")

evidence = {
    "valid_schedule_count": len(schedules),
    "example_schedules": [" ".join(o) for o in schedules[:4]],
    "option_feasibility": {k: (k in possible) for k in options},
}

print(json.dumps({"final_answer": final, "evidence": evidence}, separators=(",", ":")))
